// Original schematic swimming art; not production astronaut or wildlife designs.
export function swimmerSvg(color,frame=0){const fin=frame?8:-8;return '<svg xmlns="http://www.w3.org/2000/svg" width="100" height="70" viewBox="0 0 100 70"><g stroke="#17384a" stroke-width="2" stroke-linejoin="round"><path d="M65 31l18 '+(12+fin)+' 14 2-12 9-24-10m4-2 15 '+(31-fin)+' 15-2-10-10-25-10" fill="'+color+'"/><rect x="33" y="24" width="36" height="27" rx="9" fill="'+color+'"/><path d="M37 27l20-13 16 5M38 46l18 10 17-4" fill="none" stroke="#c4ced8" stroke-width="8"/><ellipse cx="25" cy="34" rx="20" ry="22" fill="#c4ced8"/><rect x="8" y="24" width="26" height="17" rx="6" fill="#234d61"/><path d="M12 27h14" stroke="#35d3c9" stroke-width="3"/><path d="M84 57l12-2m-9-6 10-3" stroke="#35d3c9" stroke-width="4"/></g></svg>';}
export function swimLifeSvg(id){let s='';const fish=(color,large=false)=>'<path d="M75 39l22-20v39z" fill="'+color+'"/><ellipse cx="46" cy="39" rx="'+(large?39:32)+'" ry="22" fill="'+color+'"/><circle cx="25" cy="34" r="4" fill="#102c42"/>';
 if(id==='reeds')s='<path d="M30 74Q5 40 24 9m20 65Q30 30 54 6m10 68q30-30 16-58" fill="none" stroke="#a2d29e" stroke-width="8"/>';
 else if(id==='octopus'){s='<ellipse cx="50" cy="25" rx="24" ry="23" fill="#cfaddd"/>';for(let i=0;i<8;i++)s+='<path d="M'+(31+i*5)+' 41q'+(i<4?-15:15)+' 22 '+(i<4?-22:22)+' 28" fill="none" stroke="#cfaddd" stroke-width="5"/>';s+='<circle cx="41" cy="23" r="3"/><circle cx="59" cy="23" r="3"/>';}
 else if(id==='brittle')s='<path d="M50 38L15 7m35 31L85 7M50 38L93 65M50 38v39M50 38L7 65" stroke="#ecd09c" stroke-width="8"/><circle cx="50" cy="38" r="12" fill="#ecd09c"/>';
 else if(id==='isopod'){s='<ellipse cx="50" cy="35" rx="37" ry="22" fill="#c4ced8"/>';for(let x=22;x<83;x+=10)s+='<path d="M'+x+' 18v32l-8 12" stroke="#7794a3" stroke-width="3"/>';}
 else{s=fish(id==='reef-fish'?'#ffd46d':id==='shark'?'#a5bac9':id==='whale'?'#9cbbdb':'#a0d8dd',id==='whale');if(['shark','dolphin'].includes(id))s+='<path d="M43 20l13-18 10 23" fill="#a5bac9"/>';if(id==='dolphin')s+='<path d="M19 37L2 42l24 5" fill="#a0d8dd"/>';if(id==='angler')s+='<path d="M35 20q-5-28-22-13" fill="none" stroke="#c4ced8" stroke-width="3"/><circle cx="12" cy="9" r="6" fill="#99e4d6"/>';if(id==='reef-fish')s+='<path d="M40 20v38m14-38v38" stroke="#294f68" stroke-width="5"/>';}
 return '<svg xmlns="http://www.w3.org/2000/svg" width="100" height="80" viewBox="0 0 100 80">'+s+'</svg>';
}
export function swimFindSvg(id){let s;if(id==='empty-shell')s='<path d="M50 63Q-8 33 20 13q30-25 60 0 28 20-30 50z" fill="#eed6b3"/><path d="M50 63L20 13m30 50V2m0 61L80 13" stroke="#a68172" stroke-width="3"/>';else if(id==='leaf-litter')s='<path d="M15 65Q5 5 80 12q0 60-65 53z" fill="#cba26d"/><path d="M15 65l56-44m-30 30-4-25m8 22 22-2" stroke="#775846" stroke-width="3"/>';else if(id==='rock-arch')s='<path d="M10 68V32q40-55 80 0v36H68V35q-18-24-36 0v33z" fill="#a3b7be"/>';else if(id.includes('sand')||id==='seafloor-core')s='<rect x="29" y="9" width="42" height="60" rx="9" fill="#c4ced8"/><path d="M33 34h34v28H33z" fill="#c4ad86"/><path d="M33 46h34m-34 9h34" stroke="#8e7867" stroke-width="4"/>';else s='<ellipse cx="32" cy="52" rx="23" ry="17" fill="#a9bec5"/><ellipse cx="65" cy="36" rx="25" ry="20" fill="#c4ced8"/><ellipse cx="70" cy="65" rx="18" ry="12" fill="#8fa4b1"/>';return '<svg xmlns="http://www.w3.org/2000/svg" width="100" height="80">'+s+'</svg>';}
export function swimOffset(index,phase,reduced=false){return reduced?0:Math.sin(phase*.7+index)*4;}
